using ghidra.util.table;

class EquateReferenceTableModel : GDynamicColumnTableModel<EquateReference, object>, ProgramTableModel {

	private EquateTablePlugin plugin;
	private List<EquateReference> referenceList = new();

	EquateReferenceTableModel(EquateTablePlugin plugin) : base(plugin.getTool())
    {
		this.plugin = plugin;
	}

	/* @Override */
	public string getName() {
		return "Equate References";
	}

	/* @Override */
	public List<EquateReference> getModelData() {
		return referenceList;
	}

	/* @Override */
	public Program getProgram() {
		return plugin.getProgram();
	}

	/* @Override */
	protected TableColumnDescriptor<EquateReference> createTableColumnDescriptor() {

		TableColumnDescriptor<EquateReference> descriptor = new();

		descriptor.addVisibleColumn(new EquateReferenceAddressColumn());
		descriptor.addVisibleColumn(new EquateOperandIndexColumn());

		return descriptor;
	}

	/* @Override */
	public object getDataSource() {
		return null;
	}

	void setEquate(Equate equate) {
		populateReferences(equate);
	}

	private void populateReferences(Equate equate) {
		referenceList.clear();

		Program program = getProgram();
		if (program == null) {
			return;
		}

		EquateTable equateTable = program.getEquateTable();
		if (equateTable == null || equate == null) {
			return;
		}

		referenceList.addAll(Arrays.asList(equate.getReferences()));

		fireTableDataChanged();
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int column) {
		EquateReference reference = getRowObject(row);
		OperandFieldLocation loc = new OperandFieldLocation(getProgram(), reference.getAddress(),
			null, null, null, reference.getOpIndex(), 0);
		return loc;
	}

	/* @Override */
	public ProgramSelection getProgramSelection(int[] rows) {
		AddressSet addressSet = new AddressSet();
		foreach (int row in rows) {
			EquateReference reference = getRowObject(row);
			Address addr = reference.getAddress();
			addressSet.addRange(addr, addr);
		}
		return new ProgramSelection(addressSet);
	}

	private class EquateReferenceAddressColumn : AbstractDynamicTableColumn<EquateReference, Address, object> {

		/* @Override */
		public string getColumnName() {
